/**
 * "Conditions for the Provision of the Report and Scope" -- the Agreement printed at the end of a Construction Stage report. Copied word for
 * word, with its clause numbers, from Houspect's office template "ACESPECT Pre-pour_Office Template Nov 2026.dotm" (generated from that
 * file's text and numbering; do not reword here -- update the template wording, then regenerate). It replaces the older SCOPE (AS 4349)
 * and 21 numbered conditions for this report type.
 *
 * The construction wording differs from the Dilapidation agreement (reportAgreement.ts) -- clause 4 has its construction sub-headings
 * (Construction Stage Inspections, Progress Inspections, Pre-Handover and Defects Inspections ...) -- so it is kept as its own text.
 * The template's own cross-references are kept as they are, including "clause 11.6" in clause 11.2 and "Clause 6.3" in clause 6.2.
 */
import type { AgreementBlock } from "../reportAgreement";

export const CONSTRUCTION_AGREEMENT_TITLE = "CONDITIONS FOR THE PROVISION OF THE REPORT AND SCOPE";

export const CONSTRUCTION_AGREEMENT_BLOCKS: AgreementBlock[] = [
  {"kind": "para", "text": "WHEREAS: The Client has requested the Inspector and the Inspector has agreed to carry out an inspection of the Property on the Inspection Date for the purposes of preparing the Report for the Inspection Fee on the terms and conditions set out below (“the Agreement”)."},
  {"kind": "para", "text": "Payment is due by the Inspection Date, and the Report will be released only after payment is received, unless the Client is a preferred client or a separate contractor agreement is in place."},
  {"kind": "para", "text": "This Agreement is sent to the Client with the Quotation email. No signature is required. The Client is deemed to have accepted the Quotation and this Agreement when the Client replies to and confirms the Quotation by email (see clause 17). The Quotation is valid for 30 days from the date of the Quotation."},
  {"kind": "para", "text": "Standards and guidance referred to in this Agreement: AS 4349.0–2007 Inspection of buildings – General requirements (applied by reference only, as described in the Scope of Inspection); the Domestic Building Contracts Act 1995 (Vic); and the Guide to Standards and Tolerances 2026 (Victorian Government, Building and Plumbing Commission)."},
  {"kind": "section", "n": "1", "title": "DEFINITIONS & INTERPRETATION"},
  {"kind": "clause", "n": "1.1", "text": "In this Agreement, except where the context otherwise requires:"},
  {"kind": "definition", "text": "“ACL” means the Australian Consumer Law set out in Schedule 2 to the Competition and Consumer Act 2010 (Cth), as applied in Victoria by the Australian Consumer Law and Fair Trading Act 2012 (Vic)."},
  {"kind": "definition", "text": "“Act” means the Domestic Building Contracts Act 1995 (Vic)."},
  {"kind": "definition", "text": "“Agreement” means the Quotation and these terms and conditions and any Use Conditions contained in the Report."},
  {"kind": "definition", "text": "“AS 4349” means the Australian Standard AS 4349.0–2007 Inspection of buildings – General requirements, which is referred to in this Agreement by reference only, as described in clause 4.11."},
  {"kind": "definition", "text": "“Building Works” means the works undertaken by the builder at the Property and/or the Site."},
  {"kind": "definition", "text": "“Business Day” means a day that is not a Saturday, Sunday or public holiday in Victoria."},
  {"kind": "definition", "text": "“Client” means the person, company or entity that engages Houspect to undertake the Works. For the purposes of this Agreement, the Client is the person, company or entity to whom the Quotation email is addressed and who accepts the Quotation in accordance with clause 17."},
  {"kind": "definition", "text": "“Confidential Information” means any information of Houspect whether documentary or otherwise, that may reasonably be considered commercially sensitive or indicated as such, including the terms of this Agreement, intellectual property, plans, drawings, designs, business plan and contracts, company policies, operations, work methods, processes, client information or business costs (charged or otherwise) except to the extent that such information is already in the public domain."},
  {"kind": "definition", "text": "“Defects” means an element of the Property or Site which Houspect considers does not conform with the Documents, the relevant building codes and the Act."},
  {"kind": "definition", "text": "“Documents” means the building contract, plans, specifications or any other documents on which the Building Works are being or were carried out."},
  {"kind": "definition", "text": "“Confirmation Correspondence” means confirmation of the booking, the job reference or the Inspection Date given by Houspect to the Client by email or telephone, which are the primary methods of confirmation."},
  {"kind": "definition", "text": "“Guide” means the Guide to Standards and Tolerances 2026 published by the Victorian Government (Building and Plumbing Commission, revised by the Office of the State Building Surveyor), or the edition of that Guide referred to in clause 5.7."},
  {"kind": "definition", "text": "“Houspect” means Acespect Pty Ltd trading as Houspect Victoria ABN 24 237 148 557 of PO Box 2521, MOUNT WAVERLEY VIC 3149, its related subsidiaries and franchisees and includes its inspectors."},
  {"kind": "definition", "text": "“Elevated area” includes the roof, roof space, crawl space, landing feature, and the like, generally elevated above the ground and not intended for normal use by occupants."},
  {"kind": "definition", "text": "“Inspection Date” means the date of an Inspection stated in the Quotation or Confirmation Correspondence, or otherwise agreed between the parties."},
  {"kind": "definition", "text": "“Inspection” means the inspection of the Property as per Clause 4."},
  {"kind": "definition", "text": "“Inspector” means the person who will attend the Inspection and draft the Report on instruction from Houspect."},
  {"kind": "definition", "text": "“Legislative Requirements” includes:"},
  {"kind": "item", "n": "(a)", "text": "Acts, ordinances, regulations, by-laws, orders, awards and proclamations of the Commonwealth and the State or Territory applicable to the Works; and"},
  {"kind": "item", "n": "(b)", "text": "Certifications, licenses, consent, permits, approvals and requirements of organisations having jurisdiction applicable to the Works, including all the relevant Australian Standards, the Building Codes of Australia, the National Construction Code and applicable industry standards and tolerances."},
  {"kind": "definition", "text": "“Personnel” means all Houspect’s employees and contractors properly acting for and on behalf of Houspect in relation to the Scope."},
  {"kind": "definition", "text": "“Price” means those fees Houspect has agreed with the Client in exchange for undertaking the Works. The Price is the fee stated in the Quotation."},
  {"kind": "definition", "text": "“Progress Claim” means the claim by the builder for payment in respect of the Building Works."},
  {"kind": "definition", "text": "“Property” means the structure(s) and its appurtenances to be Inspected on the Site."},
  {"kind": "definition", "text": "“Quotation” means the Booking Confirmation (or any other equivalent document or final price advice) provided by Houspect to the Client in relation to the Works. It includes the email addressed to the Client to which this Agreement is attached or linked, and the scope, fee and date stated in it."},
  {"kind": "definition", "text": "“Report” means each report prepared by Houspect on behalf of the Client for an Inspection."},
  {"kind": "definition", "text": "“Scope” means the scope of the Inspection to be undertaken by the Inspector in accordance with Clause 4."},
  {"kind": "definition", "text": "“Site” means the land, the Property or other places made available by the Client to Houspect for the purposes of performing the Works, as referred to in the Quotation."},
  {"kind": "definition", "text": "“Use Conditions” means any additional conditions contained in the Report relating to its use or application."},
  {"kind": "definition", "text": "“Variations” means variations to the Works in accordance with Clause 13."},
  {"kind": "definition", "text": "“Works” means the inspection of the Property, and the drafting of the Report."},
  {"kind": "clause", "n": "1.2", "text": "This Agreement contains the entire understanding of the parties and, unless specifically referenced in this Agreement, supersedes any other agreement, representation, tender, quote, conditions of contract, standard terms or request between the parties made or dated prior to the date of this Agreement."},
  {"kind": "clause", "n": "1.3", "text": "This Agreement shall be construed and governed in all respects in accordance with the laws of Victoria, Australia and the Commonwealth of Australia, and each party submits to the non-exclusive jurisdiction of the courts of Victoria."},
  {"kind": "clause", "n": "1.4", "text": "In this Agreement:"},
  {"kind": "item", "n": "(a)", "text": "where the Client includes one or more persons, this Agreement binds them jointly and severally;"},
  {"kind": "item", "n": "(b)", "text": "no rule of construction applies against a party merely on the basis that, that party prepared this Agreement or a portion of it;"},
  {"kind": "item", "n": "(c)", "text": "the singular includes the plural and vice versa and “including” and similar expressions are not words of limitation;"},
  {"kind": "item", "n": "(d)", "text": "where a word or phrase is defined in this Agreement, other parts of speech or grammatical forms of that word or phrase have a corresponding meaning;"},
  {"kind": "item", "n": "(e)", "text": "an expression importing a natural person includes any company, partnership, joint venture, association, corporation or other body corporate and any Government agency and includes that party's successors or permitted assigns; and"},
  {"kind": "item", "n": "(f)", "text": "a reference to a document or a statutory instrument includes an amendment or supplement to, or replacement or novation of it."},
  {"kind": "section", "n": "2", "title": "HOUSPECT'S OBLIGATIONS"},
  {"kind": "clause", "n": "2.1", "text": "Houspect will:"},
  {"kind": "item", "n": "(a)", "text": "subject to clause 4, carry out the Works with all reasonable care and skill in accordance with this Agreement; and:"},
  {"kind": "item", "n": "(b)", "text": "attend to the Scope of Inspection and provide the Report in consideration of the Price."},
  {"kind": "section", "n": "3", "title": "CLIENT'S OBLIGATIONS"},
  {"kind": "clause", "n": "3.1", "text": "In addition to its other responsibilities in this Agreement, the Client must:"},
  {"kind": "item", "n": "(a)", "text": "pay the Price in accordance with clause 11 (Payment);"},
  {"kind": "item", "n": "(b)", "text": "notify Houspect of any known or suspected hazards existing at the Site including, but not limited to, hazardous waste, adverse site conditions, noxious substances or underground utilities, and take all necessary steps to minimise the risk of exposure to such hazards;"},
  {"kind": "item", "n": "(c)", "text": "facilitate, or authorise Houspect to arrange with the owner, occupier, builder or selling agent, sufficient access to the Site and its improvements to enable Houspect to duly perform the Works in accordance with this Agreement; and"},
  {"kind": "item", "n": "(d)", "text": "provide Houspect with the Documents and any other information about the Building Works that Houspect reasonably requests for the Inspection, before the Inspection where practicable."},
  {"kind": "clause", "n": "3.2", "text": "The Client warrants that it is the owner of the Property, or is authorised by the owner and any occupier, to engage Houspect, to give Houspect access to the Site, and to receive the Report. The Client should, so far as it is able, assist Houspect to obtain the consents needed for the Inspector to enter the Site and to take photographs and notes, including from any builder, tenant, occupier, owners corporation or body corporate."},
  {"kind": "clause", "n": "3.3", "text": "Houspect will coordinate the Inspection appointment with the owner, occupier, builder or selling agent. So far as it is able, the Client should let occupiers know that the Inspector will attend and may take photographs of the Property."},
  {"kind": "section", "n": "4", "title": "SCOPE OF INSPECTION"},
  {"kind": "clause", "n": "4.1", "text": "The Inspection will be limited to the Scope outlined in the Quotation or as otherwise agreed in writing."},
  {"kind": "clause", "n": "4.2", "text": "The Inspection will be undertaken with reference to the Documents, the National Construction Code, and the Australian Standards that apply to the Building Works, and with reference to AS 4349 as described in clause 4.11. Where there exists any conflict between the Australian Standards and this Agreement, the Agreement prevails."},
  {"kind": "clause", "n": "4.3", "text": "Unless otherwise agreed in writing, the inspection will not include invasive or destructive examination or investigation for latent or hidden defects. Houspect will have no liability for any defects not reasonably manifest and visible at the time of Inspection through a visual inspection. Houspect is also not obliged to inspect any inaccessible or concealed areas of the Property, or to provide any comment in the Report in relation to:"},
  {"kind": "item", "n": "(a)", "text": "hidden or obscured defects;"},
  {"kind": "item", "n": "(b)", "text": "latent Site or Property conditions; or"},
  {"kind": "item", "n": "(c)", "text": "Building Works that are not yet constructed at the time of the Inspection."},
  {"kind": "clause", "n": "4.4", "text": "The Inspector will compare the prevailing conditions of the Property and use his/her best endeavours to indicate in the Report whether any defect is in the nature of the following:"},
  {"kind": "item", "n": "(a)", "text": "a major defect, which is a defect of sufficient magnitude where rectification has to be carried out in order to avoid unsafe conditions, loss of utility or further deterioration of the Property;"},
  {"kind": "item", "n": "(b)", "text": "a minor defect, which is a defect other than a major defect, for which a general comment is made; and"},
  {"kind": "item", "n": "(c)", "text": "a safety hazard, which includes only physical observed defects which the Inspector considers to be a safety hazard."},
  {"kind": "clause", "n": "4.5", "text": "Subject to this Clause 4, the Inspector shall inspect and report on the specific areas nominated in the Quotation (if any) and if requested, such parts of the building and its appurtenances, together with the Property generally within its boundaries where safely accessible and applicable as at the stage of construction works. This may include the following areas:"},
  {"kind": "item", "n": "(a)", "text": "the interior of the building;"},
  {"kind": "item", "n": "(b)", "text": "the roof space;"},
  {"kind": "item", "n": "(c)", "text": "the exterior of the building;"},
  {"kind": "item", "n": "(d)", "text": "the sub-floor space;"},
  {"kind": "item", "n": "(e)", "text": "the roof exterior; and"},
  {"kind": "item", "n": "(f)", "text": "any relevant feature of the Property within 30m of the main building (and within the boundaries of the Site that constitute a part of the plans submitted and accepted in the quotation)."},
  {"kind": "clause", "n": "4.6", "text": "Inspection of strata and company title Property shall be limited to the nominated residence and, subject to Clause 6, does not include common property."},
  {"kind": "clause", "n": "4.7", "text": "The Inspector shall inspect any Elevated Area only where:"},
  {"kind": "item", "n": "(a)", "text": "it is at a height at which safe reasonable access is available, or where safe and reasonable access is otherwise available; or"},
  {"kind": "item", "n": "(b)", "text": "an unobstructed line of sight is present from safe use of a 3.6m ladder and the building elements present are close enough to allow appraisal."},
  {"kind": "clause", "n": "4.8", "text": "Any areas where reasonable access is denied, not made available or inaccessible for any reason, are excluded from, and do not form part of, the Inspection and the Report. Where the Inspector is unable or unwilling pursuant to this Agreement to access areas of the Property, these areas may be noted in the Report."},
  {"kind": "clause", "n": "4.9", "text": "Any comments made in the Report in relation to the following are general in nature only and may not be relied upon in any advisory sense by the Client. The Client should engage suitably experienced contractors to review any comments made in the Report related to:"},
  {"kind": "item", "n": "(a)", "text": "plumbing;"},
  {"kind": "item", "n": "(b)", "text": "electrical;"},
  {"kind": "item", "n": "(c)", "text": "engineering;"},
  {"kind": "item", "n": "(d)", "text": "mould;"},
  {"kind": "item", "n": "(e)", "text": "toxicology;"},
  {"kind": "item", "n": "(f)", "text": "waterproofing;"},
  {"kind": "item", "n": "(g)", "text": "gas fittings;"},
  {"kind": "item", "n": "(h)", "text": "air conditioning;"},
  {"kind": "item", "n": "(i)", "text": "pests, such as termites; and"},
  {"kind": "item", "n": "(j)", "text": "asbestos"},
  {"kind": "item", "n": "(k)", "text": "swimming pool(s)."},
  {"kind": "subheading", "text": "Structural Defect Inspections"},
  {"kind": "clause", "n": "4.10", "text": "The Works will be limited to visual, line of sight inspections of the structural elements of the Property. Where necessary and accessible, this will include accessing subfloors and roof spaces to ascertain the extent of any readily identifiable defective workmanship."},
  {"kind": "subheading", "text": "Standards and Guide"},
  {"kind": "clause", "n": "4.11", "text": "AS 4349.0–2007 states that it does not include assessment of a building under construction. Accordingly, Inspections under this Agreement are not inspections carried out in accordance with AS 4349. The general principles of AS 4349.0–2007 on purpose, scope, limitations, access and reporting are applied by reference only, to the extent they are relevant to the Works."},
  {"kind": "clause", "n": "4.12", "text": "In line with AS 4349.0–2007 (clause 2.1), which is applied by reference, the parties record the following inspection agreement details:"},
  {"kind": "item", "n": "(a)", "text": "Purpose: to inspect the Building Works at the stage or stages of construction nominated in the Quotation and to report on Defects and, where the Client has engaged Houspect to do so, on whether a Progress Claim reflects the stage and progress of the Building Works."},
  {"kind": "item", "n": "(b)", "text": "Scope: the scope set out in the Quotation and in this clause 4."},
  {"kind": "item", "n": "(c)", "text": "Acceptance criteria: the Building Works are assessed against the Documents, the Act, the National Construction Code and Australian Standards that apply to the Building Works, and the Guide, as described in clauses 4.22 and 5.7."},
  {"kind": "clause", "n": "4.13", "text": "The Report is not a certificate of compliance of the Property or the Building Works with any Act, regulation, ordinance, local law, by-law, Building Code or Legislative Requirement, and cannot be relied on as such. It is not a warranty or an insurance policy against problems developing with the building in the future."},
  {"kind": "subheading", "text": "Construction Stage Inspections"},
  {"kind": "clause", "n": "4.14", "text": "Each Inspection is carried out at a stage of construction nominated in the Quotation (for example, base, frame, lock-up, fixing or completion). Each stage Inspection is a separate Inspection with its own Report, unless the Quotation states otherwise."},
  {"kind": "clause", "n": "4.15", "text": "Each Inspection is limited to the Building Works that are visible and accessible on the Inspection Date. Houspect does not supervise, manage or direct the Building Works, does not attend continuously, and is not responsible for work carried out when it is not present or that is concealed at the time of the Inspection."},
  {"kind": "clause", "n": "4.16", "text": "Houspect and the Inspector do not act as a relevant building surveyor or building inspector, or exercise any function, under the Building Act 1993 (Vic). The Report is not a mandatory notification stage inspection, a building permit, a certificate of final inspection or an occupancy permit."},
  {"kind": "subheading", "text": "Progress Inspections"},
  {"kind": "clause", "n": "4.17", "text": "Where Houspect has been engaged to perform a construction stage inspection of the Building Works, then subject to this clause 4, Houspect will inspect the areas requested by the Client for that purpose and report on whether Houspect considers the Building Works are at the stage or progress point claimed in the Progress Claim as reasonably permitted."},
  {"kind": "clause", "n": "4.18", "text": "Unless specifically agreed in writing otherwise, Houspect will not advise the Client whether the amounts claimed in the Progress Claim are reasonable or accurate. If that work is agreed (which may be subject to a variation in the Price), any assessment given as per additional service as specified in quote is an estimate only. Adherence to the payment milestones shall be the responsibility of the client per the building contract signed."},
  {"kind": "clause", "n": "4.19", "text": "Houspect is not required to report or give an opinion on whether works that are not visible to the Inspector, or whose progress is not easily ascertainable, have reached the stage or progress claimed in a Progress Claim. Furthermore, refer to Inspection Limits and Exclusions section over and above the works below:"},
  {"kind": "item", "n": "(a)", "text": "concrete works;"},
  {"kind": "item", "n": "(b)", "text": "concealed plumbing;"},
  {"kind": "item", "n": "(c)", "text": "footings below ground;"},
  {"kind": "item", "n": "(d)", "text": "concealed damp-proof course;"},
  {"kind": "item", "n": "(e)", "text": "electrical installations, including smoke alarms, light switches and fittings, TV, sound, communications and security systems;"},
  {"kind": "item", "n": "(f)", "text": "the adequacy of roof drainage as installed;"},
  {"kind": "item", "n": "(g)", "text": "gas fittings and fixtures;"},
  {"kind": "item", "n": "(h)", "text": "air conditioning;"},
  {"kind": "item", "n": "(i)", "text": "concealed tie-downs and bracing; and"},
  {"kind": "item", "n": "(j)", "text": "concealed framing timber or any areas concealed by wall linings or sidings."},
  {"kind": "clause", "n": "4.20", "text": "A statement in the Report about a progress to date is an opinion on the stage and progress of the Building Works only. It is not an approval, certification or recommendation to pay, and the Client remains responsible for its payment decisions under its building contract."},
  {"kind": "subheading", "text": "Pre-Handover and Defects Inspections"},
  {"kind": "clause", "n": "4.21", "text": "Houspect may review the Building Works and prepare a Report for the Client that outlines whether or not Houspect considers the Building Works are complete and whether there are any Defects."},
  {"kind": "clause", "n": "4.22", "text": "In considering whether an item is defective, Houspect will have regard to whether the Building Works comply with the Documents and the Act, including:"},
  {"kind": "item", "n": "(a)", "text": "the Documents;"},
  {"kind": "item", "n": "(b)", "text": "the implied warranties in section 8 of the Domestic Building Contracts Act 1995 (Vic), to the extent they relate to the matters inspected;"},
  {"kind": "item", "n": "(c)", "text": "the National Construction Code and Australian Standards that apply to the Building Works; and"},
  {"kind": "item", "n": "(d)", "text": "where relevant, the Guide, as described in clause 5.7."},
  {"kind": "clause", "n": "4.23", "text": "An opinion in the Report that an item is a Defect is an opinion only. Rectification of Defects is a matter between the Client and its builder."},
  {"kind": "subheading", "text": "Access and Site Conditions"},
  {"kind": "clause", "n": "4.24", "text": "Houspect will coordinate the Inspection appointment and access with the Client and, where applicable, the owner, occupier, builder or selling agent. So far as the Client is able, the Client should help to ensure that, on the Inspection Date:"},
  {"kind": "item", "n": "(a)", "text": "the Inspector has safe and unobstructed access to every area within the Scope, including keys, codes and passes for locked rooms, gates, sheds, roof space hatches and sub-floor access covers;"},
  {"kind": "item", "n": "(b)", "text": "electricity and water are connected and operating, where reasonably needed for the Inspection;"},
  {"kind": "item", "n": "(c)", "text": "animals are restrained or removed from the areas to be inspected;"},
  {"kind": "item", "n": "(d)", "text": "the areas to be inspected are clear of stored items, furniture and floor coverings so that building elements can be seen."},
  {"kind": "clause", "n": "4.25", "text": "The Inspector determines whether access is safe and reasonable, having regard to AS 4349. Reasonable access does not include moving furniture, stored goods or floor coverings, removing screws, bolts, fastenings or sealants from access covers, or cutting access holes."},
  {"kind": "clause", "n": "4.26", "text": "The Inspector may decline, suspend or end the Inspection, or any part of it, at any time if the Inspector considers conditions at the Site to be unsafe. This includes unsafe structures or electrical installations, suspected hazardous materials, aggressive animals, threatening behaviour, and severe weather. Areas that are not inspected for these reasons are excluded from the Inspection and the Report, and the Price remains payable."},
  {"kind": "clause", "n": "4.27", "text": "Weather, light, occupants, furnishings and stored items may limit what the Inspector is able to see. For example, a roof exterior will not be accessed when it is wet or the wind is unsafe. Houspect may reschedule an Inspection that cannot be carried out properly because of conditions at the Site."},
  {"kind": "clause", "n": "4.28", "text": "If the Inspection cannot be completed because the access or arrangements in this clause are not provided, any further attendance requested by the Client is chargeable at a reasonable additional fee notified by Houspect."},
  {"kind": "subheading", "text": "Inspection Limits and Exclusions"},
  {"kind": "clause", "n": "4.29", "text": "The Report is not an all-encompassing report dealing with the Building Works from every aspect. It is a reasonable attempt to identify Defects that are visible at the time of the Inspection. Whether a Defect is significant depends on the stage of the Building Works, and the Inspector may not comment on every minor defect or imperfection."},
  {"kind": "clause", "n": "4.30", "text": "The Inspection is a visual inspection, limited to the areas of the Property that are accessible and visible to the Inspector on the Inspection Date. Unless otherwise agreed, the Inspector does not break apart, dismantle, remove or move objects such as foliage, insulation, floor or wall coverings, linings, furnishings, appliances or personal possessions, and is not able to see inside walls, between floors, inside roofing, behind stored goods or in other concealed or obstructed areas. The Inspector does not dig, gouge, force or carry out other invasive procedures, and will not destructively probe visible timbers without the written permission of the property owner."},
  {"kind": "clause", "n": "4.31", "text": "Unless the Quotation states otherwise, the Inspector is not required to inspect or report on the following, although the Inspector may comment on them where they are readily apparent:"},
  {"kind": "item", "n": "(a)", "text": "footings below ground;"},
  {"kind": "item", "n": "(b)", "text": "concealed damp-proof course;"},
  {"kind": "item", "n": "(c)", "text": "electrical installations, including smoke detectors, light switches and fittings, TV, sound, communications and security systems;"},
  {"kind": "item", "n": "(d)", "text": "concealed plumbing;"},
  {"kind": "item", "n": "(e)", "text": "the adequacy of roof drainage as installed;"},
  {"kind": "item", "n": "(f)", "text": "gas fittings and fixtures;"},
  {"kind": "item", "n": "(g)", "text": "air-conditioning;"},
  {"kind": "item", "n": "(h)", "text": "automatic garage door mechanisms;"},
  {"kind": "item", "n": "(i)", "text": "swimming pools and associated filtration and similar equipment (a swimming pool should be the subject of a special purpose report by a suitably qualified person);"},
  {"kind": "item", "n": "(j)", "text": "the operation of fireplaces and solid fuel heaters, including chimneys and flues;"},
  {"kind": "item", "n": "(k)", "text": "alarm systems;"},
  {"kind": "item", "n": "(l)", "text": "electrical appliances, such as dishwashers, incinerators, ovens and ducted vacuum systems;"},
  {"kind": "item", "n": "(m)", "text": "paint coatings, except external protective coatings;"},
  {"kind": "item", "n": "(n)", "text": "health hazards (for example, allergies, lead content, asbestos and soil toxicity);"},
  {"kind": "item", "n": "(o)", "text": "timber and metal framing sizes and adequacy;"},
  {"kind": "item", "n": "(p)", "text": "concealed tie-downs and bracing;"},
  {"kind": "item", "n": "(q)", "text": "timber pest activity;"},
  {"kind": "item", "n": "(r)", "text": "soil conditions;"},
  {"kind": "item", "n": "(s)", "text": "control joints and related compliance;"},
  {"kind": "item", "n": "(t)", "text": "concealed framing timber or any areas concealed by wall linings or sidings; and"},
  {"kind": "item", "n": "(u)", "text": "furniture and accessories."},
  {"kind": "clause", "n": "4.32", "text": "Where large structural retaining walls are present, the Client may wish to engage a structural engineer for a special purpose report. The Inspector may, but is not required to, comment on whether an engineer is needed."},
  {"kind": "clause", "n": "4.33", "text": "Houspect does not give advice about asbestos, including whether building materials contain asbestos. If the Inspector suspects that a material may contain asbestos, Houspect may mention it, without obligation, so that the Client can have the matter confirmed by a suitably qualified person. The Client should not treat any such comment as determinative."},
  {"kind": "section", "n": "5", "title": "REPORT"},
  {"kind": "clause", "n": "5.1", "text": "The Report will be drafted from the observations taken by the Inspector during the Inspection and is subject to any Use Conditions."},
  {"kind": "clause", "n": "5.2", "text": "Houspect is only able to comment on defects that are visibly observed on the inspection date. This includes but is not limited to water ingress, subsidence, incorrect levels, and shrinkage of materials. Issues shall be presented in the report based on deemed priority aligned with standard expectations practically permitted in a visual inspection by a registered builder."},
  {"kind": "clause", "n": "5.3", "text": "Houspect will not provide any advice or guidance in respect to the cost to rectify any defects found at the Property or identified in the Report. Any comment made in that regard cannot be relied on to support a claim against Houspect."},
  {"kind": "clause", "n": "5.4", "text": "The opinion of Houspect is limited to as detailed in any written Report and the Client cannot rely on any verbal statement or expressed opinion that is not provided in writing in the Report. Houspect will provide the Works with due care and skill and within a reasonable time, to the extent required by law."},
  {"kind": "clause", "n": "5.5", "text": "Houspect may use various standards and guides when considering whether an item of work is defective. These standards may include: the Documents, Building Code of Australia, National Construction Code, Australian Standards, the Guide described in clause 5.7 and any other material that the Inspector considers relevant to the Works."},
  {"kind": "clause", "n": "5.6", "text": "Houspect will use its best endeavours to deliver the Report within 24 to 48 hours from the Inspection Date, unless the Quotation specifies otherwise. This is a target only. Time is not of the essence, and delay in delivering the Report does not entitle the Client to terminate this Agreement or to reduce the Price."},
  {"kind": "clause", "n": "5.7", "text": "The Guide:"},
  {"kind": "item", "n": "(a)", "text": "is informative only. It is an advisory document and is not part of the Victorian legislative framework, and legislation, the National Construction Code, a documented Standard and the building contract take precedence over it;"},
  {"kind": "item", "n": "(b)", "text": "does not provide a definitive determination of whether building work is defective, and is applied by the Inspector with reasonable discretion and judgement;"},
  {"kind": "item", "n": "(c)", "text": "applies to domestic building contracts entered into, or building work that commences, on or after 1 August 2026, and is not applied retrospectively. For building work that commenced before that date, Houspect may refer to the edition of the Guide, or other applicable building standard, that was published when the building work commenced; and"},
  {"kind": "item", "n": "(d)", "text": "where applied, is applied by the Inspector in the manner described in Part B (Measurement and Inspection) of the Guide, including inspecting surfaces from a normal viewing position."},
  {"kind": "clause", "n": "5.8", "text": "Dimensions given in the Report are approximate only."},
  {"kind": "clause", "n": "5.9", "text": "Any cost estimates are approximate only. Should the Client wish to define a price more accurately, trade quotations can be arranged."},
  {"kind": "clause", "n": "5.10", "text": "The Report comments on the items that the Inspector considers relevant and has observed. Where the Report does not comment on an item, the Client should not assume that the item was inspected or that it is free from defect."},
  {"kind": "section", "n": "6", "title": "COMMON PROPERTY"},
  {"kind": "clause", "n": "6.1", "text": "Houspect is under no obligation to differentiate between lot and common property."},
  {"kind": "clause", "n": "6.2", "text": "Should any lot property not be inspected as a result of the Inspector considering it is common property, the Client, subject to Clause 6.3 is to provide notice to the Inspector of any areas missed in the inspection and arrange for a secondary inspection."},
  {"kind": "section", "n": "7", "title": "COPYRIGHT"},
  {"kind": "clause", "n": "7.1", "text": "The Report is expressly produced for the sole use of the Client for the intended purpose as advised to Houspect. The client may not disseminate or provide the Report to third parties without the written authority of Houspect."},
  {"kind": "clause", "n": "7.2", "text": "The Client agrees that all copyright in the Report vests in Houspect."},
  {"kind": "clause", "n": "7.3", "text": "The Client acknowledges that any breach of this Clause 7 will result in damages to Houspect, and that damages may not be an adequate remedy to protect Houspect’s commercial interests. Any breach of Clause 7 by the Client will result in a debt immediately due and payable to Houspect to the extent of any loss, which includes but is not limited to:"},
  {"kind": "item", "n": "(a)", "text": "providing the Report to any other persons, except as permitted by this clause 7, for use in relation to the Property or otherwise;"},
  {"kind": "item", "n": "(b)", "text": "providing inspection reports to the market generally."},
  {"kind": "clause", "n": "7.4", "text": "Subject to this clause 7 and to payment of the Price, Houspect grants the Client a non-exclusive, non-transferable licence to use the Report, in its entirety, for the purpose advised to Houspect."},
  {"kind": "clause", "n": "7.5", "text": "Only the Client may rely on the Report. Houspect owes no duty and accepts no liability to any other person who receives or relies on the Report, even if Houspect has consented to the Report being provided to that person. The Client may provide the Report, in its entirety, to its legal advisers, finance provider, insurer, the owner of the Property, the builder responsible for the Building Works and its trades, and other professional advisers for the purpose advised to Houspect, but only on the basis that they are told they may not rely on it."},
  {"kind": "clause", "n": "7.6", "text": "The Report reflects the condition of the Property on the Inspection Date only. Houspect has no obligation to update the Report, and the condition of the Property may change after the Inspection Date."},
  {"kind": "section", "n": "8", "title": "WHS AND ENVIRONMENT COMPLIANCE"},
  {"kind": "clause", "n": "8.1", "text": "Houspect and its Personnel must comply with all Legislative Requirements applicable to the Works; including applicable Work Health and Safety laws (relevant to the jurisdiction in which the Supply is being provided)."},
  {"kind": "section", "n": "9", "title": "ACCURACY OF INFORMATION"},
  {"kind": "clause", "n": "9.1", "text": "In preparation of the Report, Houspect relies upon the assumptions and instructions that are provided to it by the Client."},
  {"kind": "clause", "n": "9.2", "text": "The Client acknowledges that where Houspect relies upon any assumptions or instruction by the Client, Houspect is in no way liable for any error or omission from the Report as a result of those assumptions."},
  {"kind": "clause", "n": "9.3", "text": "Houspect makes no representation and provides no warranty as to the accuracy of any representations, documentation, information or opinions provided to the Client. The Client must make its own investigations and satisfy itself as to the accuracy of any such documentation, information and representations, including those contained in the Report."},
  {"kind": "section", "n": "10", "title": "LIABILITY"},
  {"kind": "clause", "n": "10.1", "text": "Houspect is not liable for any indirect or consequential loss or damage whatsoever arising out of or in connection with the Works whether or not the possibility of such loss or damage was known or foreseeable."},
  {"kind": "clause", "n": "10.2", "text": "The Client releases and indemnifies Houspect for any claims in respect of:"},
  {"kind": "item", "n": "(a)", "text": "any breach of a term or warranty given (or not given) in this Agreement;"},
  {"kind": "item", "n": "(b)", "text": "damages arising from any invasive inspection requested by the Client."},
  {"kind": "clause", "n": "10.3", "text": "To the extent permitted by law, liability under any condition or warranty which cannot legally be excluded is limited to (at Houspect’s option):"},
  {"kind": "item", "n": "(a)", "text": "performing the Works again; or"},
  {"kind": "item", "n": "(b)", "text": "paying the cost of having the Report supplied again."},
  {"kind": "clause", "n": "10.4", "text": "Nothing in this Agreement limits the operation of Part IVAA (Proportionate liability) of the Wrongs Act 1958 (Vic). The Client acknowledges that Houspect is not responsible for loss or damage caused by others, including the builder, vendor, owner, other consultants or any occupier of the Property nor client’s decision to progress not taking further action on any recommendations and remarks made within the report."},
  {"kind": "clause", "n": "10.5", "text": "If the Client considers that the Report does not conform in a material respect with this Agreement, the Client should notify Houspect in writing as soon as reasonably practicable, and where possible within 90 days after delivery of the Report, so that Houspect can review the matter. To the extent permitted by law, Houspect’s liability in respect of any such failure is limited as set out in clause 10.3."},
  {"kind": "section", "n": "11", "title": "PAYMENT"},
  {"kind": "clause", "n": "11.1", "text": "In consideration for Houspect performing the Works, the Client agrees to pay the Price, plus any agreed variations to it, without any right of offset."},
  {"kind": "clause", "n": "11.2", "text": "The Client must pay the Price for each Inspection by the Inspection Date for that Inspection, unless a different payment arrangement has been established through a separate contractor agreement between the Client and Houspect, in which case payment must be made in accordance with that agreement. Houspect will release the Report only after payment has been received, unless the Client is a preferred client under clause 11.6 or a separate contractor agreement provides otherwise."},
  {"kind": "clause", "n": "11.3", "text": "Where the Client does not make payment in accordance with Clause 11.1, Houspect will be entitled to claim interest at the rate of 10% per annum on all outstanding amounts."},
  {"kind": "clause", "n": "11.4", "text": "If the Client cancels an Inspection:"},
  {"kind": "item", "n": "(a)", "text": "on the Inspection Date, but before the Inspector arrives at the Site, a call-out fee of $200 is payable by the Client; or"},
  {"kind": "item", "n": "(b)", "text": "without prior notice, such that Houspect is not told of the cancellation until the Inspector arrives at the Site, the full Price is payable by the Client."},
  {"kind": "clause", "n": "11.5", "text": "Where the Client is a preferred client of Houspect, payment of the Price is due within 7 days from the invoice date."},
  {"kind": "clause", "n": "11.6", "text": "Charge-out rates quoted relate to normal work. Work relating to arbitration, mediation, conciliation, expert witness or court appearance, or to other legal matters, is charged separately at Houspect’s rates."},
  {"kind": "section", "n": "12", "title": "REFERRALS"},
  {"kind": "clause", "n": "12.1", "text": "Where requested by the Client, Houspect may arrange or coordinate other specialist inspection or building services to be provided by independent third party consultants or companies, and will be entitled to charge a reasonable fee for the organisation and coordination of the same."},
  {"kind": "clause", "n": "12.2", "text": "These services may include:"},
  {"kind": "item", "n": "(a)", "text": "plumbing reports;"},
  {"kind": "item", "n": "(b)", "text": "electrical reports;"},
  {"kind": "item", "n": "(c)", "text": "engineering reports;"},
  {"kind": "item", "n": "(d)", "text": "mould reports;"},
  {"kind": "item", "n": "(e)", "text": "toxicology reports;"},
  {"kind": "item", "n": "(f)", "text": "waterproofing reports;"},
  {"kind": "item", "n": "(g)", "text": "pests reports; and"},
  {"kind": "item", "n": "(h)", "text": "asbestos reports."},
  {"kind": "clause", "n": "12.3", "text": "In arranging these services or referring the Client to a third party that provides these services, the Client acknowledges that Houspect may be paid a fee for the referral."},
  {"kind": "clause", "n": "12.4", "text": "Houspect does not in any way warrant or guarantee the services provided by these third-parties, including where those reports or observations are included in the Report, and is in no way liable for the services performed by them."},
  {"kind": "clause", "n": "12.5", "text": "Timber pest inspections (which are the subject of AS 4349.3) are not part of the Inspection. Where the Client asks, Houspect may coordinate a timber pest inspection, or other specialist inspection, by an independent provider. Any facilitated inspections through third parties would be a direct engagement of services with such party introduced by Houspect and Houspect does not take any liability nor make any representation of such party works."},
  {"kind": "section", "n": "13", "title": "REPORT VARIATIONS"},
  {"kind": "clause", "n": "13.1", "text": "Houspect may vary the Works as directed by the Client in writing or otherwise prior to the works being undertaken."},
  {"kind": "clause", "n": "13.2", "text": "The Client or Houspect may request a Variation in writing or otherwise prior to the works being undertaken."},
  {"kind": "clause", "n": "13.3", "text": "The price for any Variation to the Works will be added to, or deducted, from the Price as applicable."},
  {"kind": "clause", "n": "13.4", "text": "The Price payable in respect of a Variation will wherever possible be agreed in writing prior to the commencement of the Variation, having regard in the first instance to any agreed rates or sums. In the absence of such agreement, the Price for a Variation will be the total hours worked multiplied by the hourly rate of the inspector plus any costs incurred."},
  {"kind": "clause", "n": "13.5", "text": "If a variation is required in order to comply with any relevant law, the Client must consent."},
  {"kind": "section", "n": "14", "title": "DISPUTES"},
  {"kind": "clause", "n": "14.1", "text": "If a dispute between the parties arises in connection with the Agreement, then either party may by hand or registered post, give the other written notice of the dispute adequately identifying the issues, details and cause of the dispute."},
  {"kind": "clause", "n": "14.2", "text": "Within 14 days of receiving the written notice of the dispute, the parties must attend a conference to resolve or agree on methods to resolve the dispute."},
  {"kind": "clause", "n": "14.3", "text": "If the dispute is not resolved at the conference or within 21 days after the notice in Clause 14.1, either party may commence proceedings."},
  {"kind": "clause", "n": "14.4", "text": "The conference required by clause 14.2 may be conducted as a mediation before a mediator agreed by the parties, which may be a mediator from the Dispute Settlement Centre of Victoria. Each party bears its own costs of the dispute process, and the mediator’s fees are shared equally."},
  {"kind": "clause", "n": "14.5", "text": "Nothing in this clause 14 prevents a party from seeking urgent interlocutory or injunctive relief. Subject to this clause 14, proceedings may be brought in the Victorian Civil and Administrative Tribunal where it has jurisdiction, and otherwise in the courts of Victoria."},
  {"kind": "clause", "n": "14.6", "text": "The parties must continue to perform their obligations under this Agreement while a dispute is being resolved, except to the extent that performance is the subject of the dispute."},
  {"kind": "section", "n": "15", "title": "DEFAULTS AND TERMINATION"},
  {"kind": "clause", "n": "15.1", "text": "Any party may terminate this Contract:"},
  {"kind": "item", "n": "(a)", "text": "within 14 days of a written notice if there is a breach of the Agreement that is capable of remedy and the other party has failed to rectify that default within that timeframe; or"},
  {"kind": "item", "n": "(b)", "text": "immediately if there is a material breach of this agreement that is not capable of remedy."},
  {"kind": "clause", "n": "15.2", "text": "If the Contract is terminated for any reason:"},
  {"kind": "item", "n": "(a)", "text": "Houspect will be entitled to the unpaid value of the Works completed in accordance with the Agreement immediately prior to termination; and"},
  {"kind": "item", "n": "(b)", "text": "Houspect will be entitled to any costs associated with preparing or providing a report, notes or any other document or information to the Client; and"},
  {"kind": "item", "n": "(c)", "text": "The Client will be entitled to any documents, notes or otherwise in Houspect's possession that have been paid for by the Client."},
  {"kind": "section", "n": "16", "title": "GST"},
  {"kind": "clause", "n": "16.1", "text": "The Client must on provision of a valid tax invoice, pay Houspect the amount of GST for which Houspect becomes liable on any supply Houspect makes to the Client in connection with this Agreement."},
  {"kind": "clause", "n": "16.2", "text": "All invoices rendered by Houspect under this Agreement must comply with the GST Laws and must be sufficient to enable the Client to claim any input tax credits which may be available to it."},
  {"kind": "clause", "n": "16.3", "text": "“GST”, “GST Laws” and other terms used in this clause have the meanings used in the A New Tax System (Goods and Supply Tax) Act 1999, except that “GST Laws” includes any applicable rulings issued by the Commissioner of Taxation."},
  {"kind": "section", "n": "17", "title": "QUOTATION, ACCEPTANCE AND VALIDITY"},
  {"kind": "clause", "n": "17.1", "text": "The Quotation is valid for 30 days from the date of the Quotation. After that period, Houspect may withdraw or revise the Quotation."},
  {"kind": "clause", "n": "17.2", "text": "This Agreement is sent to the Client with the Quotation email. No signature is required. The Client is deemed to have accepted the Quotation and this Agreement, and this Agreement is binding on the Client, when the Client replies to and confirms the Quotation by email."},
  {"kind": "clause", "n": "17.3", "text": "A person who replies to and confirms the Quotation on behalf of a company, trust or other person warrants that they have authority to do so, and that person binds the Client by doing so."},
  {"kind": "clause", "n": "17.4", "text": "The parties agree that this Agreement may be entered into, and accepted, by electronic communication, consistent with the Electronic Transactions (Victoria) Act 2000 (Vic)."},
  {"kind": "clause", "n": "17.5", "text": "Any change to the scope, Price or Inspection Date takes effect only when Houspect confirms it in writing, which includes by email."},
  {"kind": "clause", "n": "17.6", "text": "These are the standard terms on which Houspect provides its services. If the Client does not agree to be bound by them, the Client should contact Houspect before the Inspection so that the services are not provided on these terms."},
  {"kind": "section", "n": "18", "title": "CONSUMER LAW AND VICTORIAN LEGISLATION"},
  {"kind": "clause", "n": "18.1", "text": "The Client’s rights under the ACL and the Australian Consumer Law and Fair Trading Act 2012 (Vic) are not affected by this Agreement, to the extent they cannot be excluded."},
  {"kind": "clause", "n": "18.2", "text": "The Works are inspection and reporting services only. Houspect does not carry out, supervise, manage or warrant domestic building work, and this Agreement is not a domestic building contract for the purposes of the Domestic Building Contracts Act 1995 (Vic)."},
  {"kind": "clause", "n": "18.3", "text": "Nothing in the Report is a statement about the Client’s rights against a builder, a vendor or an insurer, including any statutory warranty under section 8 of the Domestic Building Contracts Act 1995 (Vic) or any domestic building insurance. Time limits may apply to those rights. The Client should take legal advice about them."},
  {"kind": "section", "n": "19", "title": "PRIVACY"},
  {"kind": "clause", "n": "19.1", "text": "Houspect shall take all reasonably possible efforts to handle personal information in accordance with the Privacy Act 1988 (Cth) and the Australian Privacy Principles, to the extent they apply to Houspect, and with any other privacy law that applies to it in Victoria (including, where applicable, the Privacy and Data Protection Act 2014 (Vic) and the Health Records Act 2001 (Vic))."},
  {"kind": "clause", "n": "19.2", "text": "Houspect collects personal information about the Client and about occupiers of the Property, such as names, contact details, the address of the Property, access arrangements, and photographs and notes taken during the Inspection. Houspect collects and uses this information to:"},
  {"kind": "item", "n": "(a)", "text": "provide a Quotation and carry out the Works;"},
  {"kind": "item", "n": "(b)", "text": "prepare the Report and keep records of the Inspection;"},
  {"kind": "item", "n": "(c)", "text": "invoice and collect payment;"},
  {"kind": "item", "n": "(d)", "text": "arrange referrals under clause 12, where the Client asks for them;"},
  {"kind": "item", "n": "(e)", "text": "manage quality and training, and handle complaints and disputes; and"},
  {"kind": "item", "n": "(f)", "text": "comply with its legal obligations."},
  {"kind": "clause", "n": "19.3", "text": "Houspect may disclose personal information to its franchisor and related entities, to its Personnel, to service providers that support its business (such as booking, payment, reporting and data storage providers), to professional advisers and insurers, to any referral provider the Client has asked Houspect to engage, and where required or authorised by law. If Houspect discloses personal information overseas, it will take reasonable steps in accordance with the Australian Privacy Principles."},
  {"kind": "clause", "n": "19.4", "text": "The Client must not give Houspect the personal information of another person unless the Client is entitled to do so. Houspect will take reasonable steps to let occupiers and other affected persons know how it handles their information, and the Client should help where it is able to."},
  {"kind": "clause", "n": "19.5", "text": "Houspect takes reasonable steps to keep personal information secure. If an eligible data breach occurs, Houspect will notify the persons and the regulator as required by the Privacy Act 1988 (Cth)."},
  {"kind": "clause", "n": "19.6", "text": "The Client and other individuals may ask to access or correct personal information that Houspect holds about them, or may make a privacy complaint, by writing to Houspect Victoria at PO Box 2521, MOUNT WAVERLEY VIC 3149 or by email to info@houspectvic.com.au."},
];
